#include "postquantiquecoin/wallet/CoinSelection.h"
#include <algorithm>
namespace pqc { CoinSelectionResult CoinSelection::SelectSmallestAbove(std::vector<UTXO> u,uint64_t target){ std::sort(u.begin(),u.end(),[](auto&a,auto&b){return a.amountAtoms<b.amountAtoms;}); CoinSelectionResult r; for(const auto& x:u){ r.selected.push_back(x); r.total+=x.amountAtoms; if(r.total>=target){r.success=true;break;} } return r;} CoinSelectionResult CoinSelection::SelectBranchAndBound(std::vector<UTXO> u,uint64_t t){return SelectSmallestAbove(std::move(u),t);} CoinSelectionResult CoinSelection::SelectPrivacyAware(std::vector<UTXO> u,uint64_t t){return SelectSmallestAbove(std::move(u),t);} CoinSelectionResult CoinSelection::SelectConsolidation(std::vector<UTXO> u,uint64_t t){ std::sort(u.begin(),u.end(),[](auto&a,auto&b){return a.amountAtoms>b.amountAtoms;}); return SelectSmallestAbove(std::move(u),t);} }
